				savedSetupMessage.setSecondaryLabelPlacement( secPosition );
				
				Debug::trace("LabelApplierManager.SendTwoLabelPositions","setSecondaryLabelPlacement()");
				Debug::trace("LabelApplierManager.SendTwoLabelPositions","getSecondaryRotation():" + Integer::toString(po.getSecondaryRotation()));
				//if pre-printed label change rotation 180 degrees from orginal.
