bool LabelApplierManager::isEvolutionLabelApplier() const
{
	if (laKind == EvolutionLabelApplier)
		return true;
	else
		return false;
}

bool LabelApplierManager::isCompactLabelApplier() const
{
	if (laKind == CompactLabelApplier)
		return true;
	else
		return false;
}

bool LabelApplierManager::isCompactLabelApplier_EPSAC2() const
{
	if (laKind == CompactLabelApplier_EPSAC2)
		return true;
	else
		return false;
}

bool LabelApplierManager::isILA() const
{
	if (laKind == ILA)
		return true;
	else
		return false;
}

bool LabelApplierManager::isBakeryCLA() const
{
	if (isCompactLabelApplier() && forAWSBakeryCLA)
		return true;
	else
		return false;
}
